    : refuse('integration_deadline', `The ${task.phase} session did not finish within ${limits.unit_deadline_ms} ms`, {role: task.role}));
  const response = await within(ask({...task, ...(unit ? {unit} : {})}), limits.unit_deadline_ms, expired);
